<?php

declare(strict_types=1);

namespace App\Notifications;

use Illuminate\Auth\Notifications\VerifyEmail as BaseVerifyEmail;
use Illuminate\Notifications\Messages\MailMessage;

/**
 * FeedGenix-branded email verification message. Replaces Laravel's default
 * "Verify Email Address" mail with copy that fits the brand voice (calm,
 * Swiss, no exclamation marks, sentence case) and explains the trial state
 * the user just entered.
 *
 * The signed URL is generated by the parent class via the verification.verify
 * route — same logic as default, just different copy + a single CTA.
 */
class VerifyEmailNotification extends BaseVerifyEmail
{
    /**
     * Build the mail message. Parent provides verificationUrl().
     */
    public function toMail($notifiable): MailMessage
    {
        $url = $this->verificationUrl($notifiable);

        return (new MailMessage())
            ->subject('Verify your FeedGenix email — your 7-day trial is ready')
            ->greeting('Welcome to FeedGenix.')
            ->line("You're a click away from your 7-day trial. Confirm this is your email so we can ship your account safely.")
            ->action('Verify email and start trial', $url)
            ->line('The link is valid for 60 minutes. After that, sign in and ask for a new one.')
            ->line("If you didn't sign up for FeedGenix, you can ignore this email — no account will be created against this address.")
            ->salutation("— The FeedGenix team\nZürich");
    }
}
